              "{\"headline\":\"Phase one trade deal may not get signed before additional tariffs kick in: US Chamber of Commerce\",\"dateCreated\":\"2019-11-22T06:28:15+0000\",\"datePublished\":\"2019-11-22T06:28:15+0000\",\"dateModified\":\"2019-11-22T06:28:15+0000\",\"author\":[{\"name\":\"Saheli Roy Choudhury\"}],\"publisher\":{\"name\":\"CNBC\",\"foundingDate\":\"1989-04-17\",\"sameAs\":[\"https://www.facebook.com/cnbc\",\"https://www.instagram.com/cnbc\",\"https://www.linkedin.com/company/cnbc\",\"https://twitter.com/cnbc\",\"https://en.wikipedia.org/wiki/CNBC\",\"https://www.youtube.com/cnbc\"]},\"articleSection\":\"Business News\",\"keywords\":[\"cnbc\",\"Articles\",\"Asia Economy\",\"Politics\",\"World economy\",\"U.S. Economy\",\"Trade\",\"China\",\"United States\",\"Donald J. Trump\",\"US Economy\",\"China Economy\",\"World Economy\",\"China Politics\",\"China Markets\",\"Asia Markets\",\"U.S. Markets\",\"Europe Markets\",\"Business News\",\"Economy\",\"Economic Measures\",\"source:tagname:CNBC Asia Source\"],\"video\":{\"description\":\"Andrew Sheets of Morgan Stanley says a phase one trade deal between the U.S. and China may \\\"be as good as it gets.\\\"\",\"duration\":\"PT2M45S\",\"name\":\"Phase two, three of the trade deal may remain 'distant': Morgan Stanley\",\"uploadDate\":\"2019-11-20T09:02:50+0000\"}}"
            ]
